import org.openqa.selenium.*;import org.openqa.selenium.chrome.*;import java.nio.file.*;
public class ReportCapture{public static void main(String[]args)throws Exception{System.setProperty("webdriver.chrome.driver",Paths.get("verification/tools/chromedriver-win64/chromedriver.exe").toAbsolutePath().toString());ChromeOptions o=new ChromeOptions();o.setBinary("C:/Program Files/Google/Chrome/Application/chrome.exe");o.addArguments("--headless=new","--window-size=1600,1200");WebDriver d=new ChromeDriver(o);try{String[] pages={"index.html","jmeter/users-100-burst/dashboard/index.html","jmeter/users-200-burst/dashboard/index.html","jmeter/users-500-burst/dashboard/index.html"};for(int i=0;i<pages.length;i++){d.get(Paths.get("verification/results",pages[i]).toAbsolutePath().toUri().toString());Thread.sleep(1600);Files.write(Paths.get("verification/results",i==0?"test-summary.png":"jmeter-"+new int[]{0,100,200,500}[i]+"-dashboard.png"),((TakesScreenshot)d).getScreenshotAs(OutputType.BYTES));}}finally{d.quit();}}}
